-- IRFE demo database: schema (60 tables), job-order function, RLS and storage bucket.
-- Structure only - no real data. Run once on a FRESH Supabase project, then run 02_seed.sql.

create table if not exists profiles ( id uuid not null, full_name text, role text default 'manager'::text not null, created_at timestamptz default now(), username text unique, email text, status text default 'active'::text, zoom_level int4 default 100, primary key (id));
create table if not exists projects ( id text not null, name text not null, client text, type text, status text default 'Active'::text, start_date date, end_date date, value numeric default 0, progress int4 default 0, manager text, notes text, created_at timestamptz default now(), po_number text unique, quotation_id text, invoice_id text, dr_number text, delivery_date_needed date, actual_delivery_date date, payment_terms_days int4 default 30, cr_number text, collection_date date, collection_amount numeric default 0, date_collected date, payment_status text default 'Unpaid'::text, po_total_value numeric default 0, progress_manual bool default false not null, primary key (id));
create table if not exists quotations ( id text not null, client text not null, date date, valid_until date, status text default 'Draft'::text, notes text, tax numeric default 0.12, created_at timestamptz default now(), company_name text, address text, attention text, delivery_date text default 'Negotiable'::text, payment_terms text default '30 Days'::text, prepared_by text, vat_mode text default 'excluded'::text, signatory_position text default 'CEO/Sales Manager'::text, signature_data text, commission_referrer text, commission_pct numeric default 0, commission_status text default 'unpaid'::text, discount_pct numeric default 0, po_number text, version_number int4 default 1, root_quotation_id text, job_order_number text, primary key (id));
create table if not exists quotation_items ( id uuid default gen_random_uuid() not null, quotation_id text, description text, qty numeric default 1, unit text, price numeric default 0, kind text default 'item'::text, position int4 default 0, image_data text, cost_breakdown jsonb, dimension text, show_on_export bool default false, line_uid text, details text, image_scale numeric, primary key (id));
create table if not exists invoices ( id text not null, quotation_id text, client text not null, date date, due_date date, status text default 'Pending'::text, notes text, tax numeric default 0.12, created_at timestamptz default now(), company_name text, address text, attention text, prepared_by text, vat_mode text default 'excluded'::text, cr_number text, signatory_position text default 'CEO/Sales Manager'::text, signature_data text, payment_terms text default '30 Days'::text, dr_number text, delivery_date date, collection_date date, collection_amount numeric, po_number text, primary key (id));
create table if not exists invoice_items ( id uuid default gen_random_uuid() not null, invoice_id text, description text, qty numeric default 1, unit text, price numeric default 0, kind text default 'item'::text, position int4 default 0, image_data text, dimension text, show_on_export bool default false, source_line_uid text, details text, image_scale numeric, primary key (id));
create table if not exists employees ( id text not null, name text not null, role text, department text, employment_type text default 'Salaried'::text, rate numeric default 0, contact text, status text default 'Active'::text, created_at timestamptz default now(), employment_status text default 'Regular'::text, gov_contributions_exempt bool default false, philhealth_exempt bool default false, pagibig_doubled bool default false, pagibig_exempt bool default false, full_day_pay bool default false, fixed_salary bool default false, monthly_salary numeric default 0, ot_exempt bool default false, vl_allotment numeric default 5, sl_allotment numeric default 5, philhealth_doubled bool default false, sss_exempt bool default false, hire_date date, primary key (id));
create table if not exists payroll ( id uuid default gen_random_uuid() not null, employee_id text, period text not null, days_worked numeric default 22, overtime_hours numeric default 0, allowance numeric default 0, sss numeric default 0, philhealth numeric default 0, pagibig numeric default 0, tax numeric default 0, status text default 'Pending'::text, created_at timestamptz default now(), cash_advance_deduction numeric default 0, payroll_run_id uuid, sunday_days numeric default 0, sunday_pay numeric default 0, night_diff_hours numeric default 0, night_diff_pay numeric default 0, leave_days numeric default 0, leave_pay numeric default 0, regular_holiday_days numeric default 0, regular_holiday_pay numeric default 0, special_holiday_days numeric default 0, special_holiday_pay numeric default 0, company_deduction numeric default 0, loan_deduction numeric default 0, remaining_leave numeric, deduction_lines jsonb default '[]'::jsonb, bday_amount numeric default 0, leave_dates jsonb default '[]'::jsonb, other_deductions numeric default 0, overtime_pay numeric default 0, regular_pay numeric, rate_breakdown jsonb, primary key (id));
create table if not exists expenses ( id text not null, date date, category text, description text not null, amount numeric default 0, payment_method text default 'Cash'::text, receipt text, status text default 'Paid'::text, created_at timestamptz default now(), primary key (id));
create table if not exists inventory ( id text not null, name text not null, unit text, quantity numeric default 0, min_stock numeric default 0, unit_cost numeric default 0, supplier text, created_at timestamptz default now(), category text, primary key (id));
create table if not exists equipment ( id text not null, name text not null, brand text, status text default 'Available'::text, assigned_to text, last_maintenance date, created_at timestamptz default now(), price numeric default 0, date_acquired date, quantity int4 default 1, primary key (id));
create table if not exists cash_advances ( id text not null, employee_id text not null, date_issued date default CURRENT_DATE not null, amount numeric default 0 not null, balance numeric default 0 not null, status text default 'Open'::text not null, notes text, created_at timestamptz default now(), bank_transaction_id text, primary key (id));
create table if not exists cash_advance_payments ( id uuid default gen_random_uuid() not null, cash_advance_id text not null, payroll_id uuid, amount numeric default 0 not null, date date default CURRENT_DATE not null, method text default 'Payroll Deduction'::text not null, notes text, created_at timestamptz default now(), primary key (id));
