create table if not exists equipment_loan_payments ( id uuid default gen_random_uuid() not null, loan_id text not null, expense_id text, amount numeric default 0 not null, date date default CURRENT_DATE not null, method text default 'Linked Expense'::text, notes text, created_at timestamptz default now(), primary key (id));
create table if not exists sss_brackets ( id uuid default gen_random_uuid() not null, salary_from numeric not null, salary_to numeric, ee_contribution numeric not null, effective_year int4 default 2025 not null, primary key (id));
