create or replace function public.get_next_job_order_number() returns text
language plpgsql security definer set search_path = public as $$
declare d date := (now() at time zone 'Asia/Manila')::date; n int;
begin
  insert into public.job_order_counters(order_date, last_number) values (d, 1)
  on conflict (order_date) do update set last_number = public.job_order_counters.last_number + 1
  returning last_number into n;
  return 'JO-' || to_char(d,'YYMMDD') || '-' || lpad(n::text,3,'0');
end $$;

do $$ declare r record; begin
  for r in select tablename from pg_tables where schemaname='public' loop
    execute format('alter table public.%I enable row level security', r.tablename);
    execute format('drop policy if exists demo_authenticated_all on public.%I', r.tablename);
    execute format('create policy demo_authenticated_all on public.%I for all to authenticated using (true) with check (true)', r.tablename);
  end loop; end $$;

insert into storage.buckets (id, name, public) values ('attachments','attachments',false) on conflict (id) do nothing;
drop policy if exists demo_attachments_all on storage.objects;
create policy demo_attachments_all on storage.objects for all to authenticated using (bucket_id='attachments') with check (bucket_id='attachments');
